/* 先读袋子数 n，再读贴纸总数 m；总量可达 10^12。 */
#include <stdio.h>
int main(void)  {
    long long n, m;
    scanf("%lld%lld", &n, &m);
    /* 整数除法 m/n 得到最大等份，不逐张或逐袋模拟。 */
    /* 按商、余数顺序输出，m<n 时每袋 0 张也是合法答案。 */
    printf("%lld %lld\n", m / n, m % n);
    return 0;
}

